const c=["facebook.com","instagram.com","youtube.com","youtu.be","tiktok.com","twitter.com","x.com","reddit.com","pinterest.com","snapchat.com","whatsapp.com","telegram.org","discord.com","twitch.tv","netflix.com","hulu.com","disneyplus.com","spotify.com","soundcloud.com","amazon.com","ebay.com","aliexpress.com","wikipedia.org"];function r(o){return o.toLowerCase().replace(/^www\./,"")}function m(o){if(!o)return!1;const e=r(o);return c.some(t=>e===t||e.endsWith(`.${t}`))}function n(o){if(!o)return!1;try{return m(new URL(o).hostname)}catch{return!1}}export{n as i};
